// DETERMINISTIC: validate-by-coercion + map self-assessment to scores + intensity + directive.
const f = $input.first().json;
const get = (k) => (f[k] !== undefined && f[k] !== null ? f[k] : '');

const company = String(get('Company')).trim() || 'the company';
const role = String(get('Role')).trim() || 'SDE';
const recipientEmail = String(get('Your Email')).trim();

let daysLeft = parseInt(get('Days Until Interview'), 10);
let dailyHours = parseFloat(get('Daily Hours You Can Grind'));
if (!Number.isFinite(daysLeft) || daysLeft < 1) daysLeft = 7;   // safe defaults (no gate node)
if (daysLeft > 60) daysLeft = 60;
if (!Number.isFinite(dailyHours) || dailyHours < 0.5) dailyHours = 2;

const calendarEnabled = String(get('Sync day plan to Google Calendar?')).trim().toLowerCase() === 'yes';
const dsaSituation = String(get('Current DSA Situation')).trim();
const hrSituation = String(get('Behavioural Round Situation')).trim();

const toArr = (v) => Array.isArray(v) ? v : (v ? String(v).split(',').map(s => s.trim()).filter(Boolean) : []);
const weakTopics = toArr(get('Weak DSA Topics'));
const strongTopics = toArr(get('Strong DSA Topics'));

const dsaScoreMap = {
  "I finished DSA once. Memory left the chat.": 35, "I'm good. Just need revision.": 75,
  "I know concepts but my coding speed is tragic.": 55, "I know DSA until the follow-up question.": 60,
  "I watched Striver. Didn't practice.": 30, "I bookmarked everything. Studied nothing.": 15,
  "Never seriously learned DSA.": 5, "I'm cracked. Bring the interview.": 90,
};
const hrScoreMap = {
  "Never prepared.": 10, "I have stories but they sound boring.": 45, "I forget my examples on the spot.": 35,
  "I know STAR but don't STAR.": 50, "Need company-specific prep.": 60,
  "Confident, just need to revise.": 80, "I fake confidence successfully.": 55,
};
const readiness = dsaScoreMap[dsaSituation] ?? 40;
const hrScore = hrScoreMap[hrSituation] ?? 40;

let intensity = 'sprint', planningDirective = '';
if (daysLeft <= 4) { intensity = 'crisis';
  planningDirective = 'Triage only: highest-frequency patterns and most-asked company questions, daily timed mocks, no new topics.'; }
else if (daysLeft >= 15) { intensity = 'marathon';
  planningDirective = 'Build fundamentals on weak topics early, ramp difficulty, regular mocks in the back third, leave buffer days.'; }
else { intensity = 'sprint';
  planningDirective = 'Cover high-ROI topics first, fix weak areas by frequency, daily mixed practice plus a mock every 2-3 days.'; }

return [{ json: {
  company, role, recipientEmail, daysLeft, dailyHours, calendarEnabled,
  dsaSituation, hrSituation, readiness, hrScore, weakTopics, strongTopics, intensity, planningDirective,
}}];

// DETERMINISTIC: read Gemini OR Groq response, parse JSON, fall back to defaults.
const item = $input.first().json || {};
let text = item?.candidates?.[0]?.content?.parts?.[0]?.text
        || item?.choices?.[0]?.message?.content
        || '';
function parseJson(t, fb){
  if (!t) return fb;
  try { return JSON.parse(t); } catch(e){}
  const m = t.match(/\{[\s\S]*\}/);
  if (m){ try { return JSON.parse(m[0]); } catch(e){} }
  return fb;
}

const intel = parseJson(text, {
  process_overview: 'Typical SDE loop: online assessment, 2-4 DSA rounds, and a behavioural round.',
  common_topics: [], company_questions: [], behavioural_signals: []
});
return [{ json: { intel } }];

// DETERMINISTIC: read Gemini OR Groq response, parse JSON, fall back to defaults.
const item = $input.first().json || {};
let text = item?.candidates?.[0]?.content?.parts?.[0]?.text
        || item?.choices?.[0]?.message?.content
        || '';
function parseJson(t, fb){
  if (!t) return fb;
  try { return JSON.parse(t); } catch(e){}
  const m = t.match(/\{[\s\S]*\}/);
  if (m){ try { return JSON.parse(m[0]); } catch(e){} }
  return fb;
}

const reality = parseJson(text, {
  reality_check: 'Time is short. Stop collecting resources and start solving timed problems on your weak topics today.',
  high_roi_topics: [], skip_topics: []
});
return [{ json: { reality } }];

// DETERMINISTIC: read Gemini OR Groq response, parse JSON, fall back to defaults.
const item = $input.first().json || {};
let text = item?.candidates?.[0]?.content?.parts?.[0]?.text
        || item?.choices?.[0]?.message?.content
        || '';
function parseJson(t, fb){
  if (!t) return fb;
  try { return JSON.parse(t); } catch(e){}
  const m = t.match(/\{[\s\S]*\}/);
  if (m){ try { return JSON.parse(m[0]); } catch(e){} }
  return fb;
}

// DETERMINISTIC: force the schema the planner was told to produce.
const plan = parseJson(text, {});
const norm = $('Validate and Normalize').first().json;
const days = norm.daysLeft, maxH = norm.dailyHours;
let dayPlan = Array.isArray(plan.day_plan) ? plan.day_plan : [];
dayPlan = dayPlan.slice(0, days).map((d, i) => ({
  day: i + 1,
  focus: String((d && d.focus) || 'Mixed practice').slice(0, 80),
  tasks: Array.isArray(d && d.tasks) ? d.tasks.slice(0, 3).map(t => String(t).slice(0, 120)) : ['Solve 4-6 problems','Review mistakes'],
  hours: Math.min(Number(d && d.hours) || maxH, maxH),
}));
while (dayPlan.length < days) {
  const i = dayPlan.length;
  dayPlan.push({ day: i + 1, focus: 'Buffer: revision and mock', tasks: ['Revise weak topics','1 timed mock','Review mistakes'], hours: maxH });
}
return [{ json: {
  strategy_rationale: String(plan.strategy_rationale || 'Front-loads the highest-frequency topics so even partial completion maximizes expected score.').slice(0, 400),
  day_plan: dayPlan, planned_days: dayPlan.length
}}];

// DETERMINISTIC: read Gemini OR Groq response, parse JSON, fall back to defaults.
const item = $input.first().json || {};
let text = item?.candidates?.[0]?.content?.parts?.[0]?.text
        || item?.choices?.[0]?.message?.content
        || '';
function parseJson(t, fb){
  if (!t) return fb;
  try { return JSON.parse(t); } catch(e){}
  const m = t.match(/\{[\s\S]*\}/);
  if (m){ try { return JSON.parse(m[0]); } catch(e){} }
  return fb;
}

const behavioural = parseJson(text, {
  framework_tip: 'Use STAR: Situation, Task, Action, Result. Lead with impact and quantify the result.',
  company_values: [], practice_questions: [], sample_story_outline: ''
});
return [{ json: { behavioural } }];

// DETERMINISTIC: stitch all agent outputs into a styled HTML email.
const norm = $('Validate and Normalize').first().json;
const intel = ($('Parse Intelligence').first().json.intel) || {};
const reality = ($('Parse Reality').first().json.reality) || {};
const road = $('Validate and Repair Roadmap').first().json || {};
const beh = ($('Parse Behavioural').first().json.behavioural) || {};

const esc = (s) => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const ul = (arr) => (Array.isArray(arr) && arr.length)
  ? '<ul style="margin:6px 0 0;padding-left:20px">' + arr.map(x => '<li style="margin:2px 0">' + esc(x) + '</li>').join('') + '</ul>'
  : '<p style="margin:6px 0 0;color:#888">None provided.</p>';

const rows = (road.day_plan || []).map(d =>
  '<tr>' +
  '<td style="padding:8px 10px;border-bottom:1px solid #eee;font-weight:600;white-space:nowrap;vertical-align:top">Day ' + d.day + '</td>' +
  '<td style="padding:8px 10px;border-bottom:1px solid #eee">' + esc(d.focus) +
    '<div style="color:#555;font-size:13px;margin-top:4px">' + (d.tasks || []).map(esc).join(' &bull; ') + '</div></td>' +
  '<td style="padding:8px 10px;border-bottom:1px solid #eee;text-align:right;white-space:nowrap;vertical-align:top">' + d.hours + ' h</td>' +
  '</tr>'
).join('');

const section = (title, body) =>
  '<h2 style="font-size:16px;margin:24px 0 4px;color:#111;border-bottom:2px solid #f0f0f0;padding-bottom:4px">' + title + '</h2>' + body;

const reportHtml =
'<div style="font-family:-apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;max-width:640px;margin:0 auto;color:#222;line-height:1.5">' +
  '<div style="background:#0f172a;color:#fff;padding:20px 24px;border-radius:10px 10px 0 0">' +
    '<div style="font-size:20px;font-weight:700">Interview Prep Plan</div>' +
    '<div style="opacity:.88;margin-top:4px">' + esc(norm.company) + ' &middot; ' + esc(norm.role) + '</div>' +
    '<div style="opacity:.7;font-size:13px;margin-top:8px">' + norm.daysLeft + ' days left &middot; ' + norm.dailyHours + ' h/day &middot; ' + esc(norm.intensity) + ' mode</div>' +
  '</div>' +
  '<div style="border:1px solid #eee;border-top:none;border-radius:0 0 10px 10px;padding:8px 24px 24px">' +
    section('1. Interview Intelligence', '<p style="margin:6px 0 0">' + esc(intel.process_overview) + '</p><p style="margin:12px 0 0;font-weight:600">Commonly tested topics</p>' + ul(intel.common_topics)) +
    section('2. Reality Check', '<blockquote style="margin:8px 0 0;padding:10px 14px;background:#fff7ed;border-left:4px solid #fb923c;border-radius:4px">' + esc(reality.reality_check) + '</blockquote>') +
    section('3. Why this plan exists', '<p style="margin:6px 0 0">' + esc(road.strategy_rationale) + '</p>') +
    section('4. High-ROI topics', ul(reality.high_roi_topics) + '<p style="margin:12px 0 0;font-weight:600">Safe to deprioritise</p>' + ul(reality.skip_topics)) +
    section('5. Company-specific questions', ul(intel.company_questions)) +
    section('6. Day-by-Day Roadmap', '<table style="width:100%;border-collapse:collapse;margin-top:8px;font-size:14px"><tbody>' + rows + '</tbody></table>') +
    section('7. Behavioural / HR Prep', '<p style="margin:6px 0 0;font-style:italic">' + esc(beh.framework_tip) + '</p>' +
      '<p style="margin:12px 0 0;font-weight:600">Values screened for</p>' + ul(beh.company_values) +
      '<p style="margin:12px 0 0;font-weight:600">Practice questions</p>' + ul(beh.practice_questions) +
      '<p style="margin:12px 0 0;font-weight:600">STAR story skeleton</p><p style="margin:6px 0 0">' + esc(beh.sample_story_outline) + '</p>') +
    section('8. Final Note', '<p style="margin:6px 0 0">You have ' + norm.daysLeft + ' days and a concrete plan. Solve out loud, ask clarifying questions, and keep moving. Good luck.</p>') +
    '<p style="margin:24px 0 0;font-size:12px;color:#999">Generated automatically via Tavily web search and Gemini (Groq fallback).</p>' +
  '</div>' +
'</div>';

return [{ json: { reportHtml, company: norm.company, recipientEmail: norm.recipientEmail } }];

// DETERMINISTIC: turn the day_plan into one calendar event per day (timed 18:00 reminder).
const plan = $('Validate and Repair Roadmap').first().json || {};
const days = plan.day_plan || [];
const out = days.map((d) => {
  const start = new Date(); start.setHours(18, 0, 0, 0); start.setDate(start.getDate() + (d.day - 1));
  const end = new Date(start); end.setHours(start.getHours() + 1);
  return { json: {
    summary: 'Prep Day ' + d.day + ': ' + d.focus,
    description: (d.tasks || []).map(t => '- ' + t).join('\n') + '\nPlanned hours: ' + d.hours,
    start: start.toISOString(),
    end: end.toISOString(),
  }};
});
return out.length ? out : [{ json: { skip: true } }];
